: [{\"coord\": [158, 1412, 811, 1497], \"page_id\": 88}], \"content\": \"1 Beginning July 1974, the International Monetary Fund adopted a technique for valuing the SDRs based on a weighted average of exchange rates for the currencies of selected member countries. The U.S. SDR holdings and allocations are valued on this basis beginning July 1974.\", \"description\": null, \"id\": 4, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [842, 1410, 1475, 1539], \"page_id\": 88}], \"content\": \"Note\\u2014Annual balance sheets for fiscal years 1934 through 1940 appeared in the 1940 \\\"Annual Report of the Secretary of the Treasury\\\" and those for succeeding years appeared in subsequent reports through 1980. Quarterly balance sheets beginning with December 31, 1938, have been published in the \\\"Treasury Bulletin.\\\" Data from inception to September 30, 1978, may be found on the statements published in the January 1979 \\\"Treasury Bulletin.\\\"\", \"description\": null, \"id\": 5, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [1060, 186, 1504, 464], \"page_id\": 89}], \"content\": null, \"description\": null, \"id\": 0, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [1481, 101, 1528, 132], \"page_id\": 90}], \"content\": \"84\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [548, 245, 1086, 285], \"page_id\": 90}], \"content\": \"TABLE TF-6A.\\u2014Highway Trust Fund\", \"description\": null, \"id\": 1, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [138, 295, 811, 427], \"page_id\": 90}], \"content\": \"The following information is released according to the provisions of the Byrd Amendment [codified at 26 United States Code 9503(d)] and represents estimates concerning the Highway Trust Fund at the close of the next fiscal year.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 295, 1506, 438], \"page_id\": 90}], \"content\": \"The 48-month revenue estimates for the highway and mass transit accounts, respectively, include the latest estimates received from Treasury's Office of Tax Analysis for excise taxes, net of refunds.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [705, 585, 953, 627], \"page_id\": 90}], \"content\": \"Highway Account\", \"description\": null, \"id\": 4, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [688, 632, 958, 662], \"page_id\": 90}], \"content\": \"(In billions of dollars. Source: DOT)\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [168, 672, 1494, 1004], \"page_id\": 90}], \"content\": \"<table><tr><td>Commitments (unobligated balances plus unpaid obligations, fiscal year 2026)</td><td>134</td></tr><tr><td>less:</td><td></td></tr><tr><td>Cash balance (fiscal year 2026)</td><td>41</td></tr><tr><td>Unfunded authorizations (fiscal year 2026)</td><td>93</td></tr><tr><td>48-month revenue estimate (fiscal years 2027, 2028, 2029, and 2030)</td><td>146</td></tr></table>\", \"description\": null, \"id\": 6, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [157, 1042, 778, 1091], \"page_id\": 90}], \"content\": \"Note\\u2014Detail may not add due to rounding. Reflects extension of authorized revenue collection and funding levels prescribed in P.L. 117-58.\", \"description\": null, \"id\": 7, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [831, 1044, 1393, 1089], \"page_id\": 90}], \"content\": \"Note\\u2014 48-month revenue estimate reflects FY 2025 Midsession Review projections.\", \"description\": null, \"id\": 8, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [674, 1219, 985, 1252], \"page_id\": 90}], \"content\": \"Mass Transit Account\", \"description\": null, \"id\": 9, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [694, 1263, 958, 1292], \"page_id\": 90}], \"content\": \"(In billions of dollars. Source: DOT)\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [169, 1301, 1494, 1629], \"page_id\": 90}], \"content\": \"<table><tr><td>Commitments (unobligated balances plus unpaid obligations, fiscal year 2026)</td><td>59</td></tr><tr><td>less:</td><td></td></tr><tr><td>Cash balance (fiscal year 2026)</td><td>16</td></tr><tr><td>Unfunded authorizations (fiscal year 2026)</td><td>43</td></tr><tr><td>48-month revenue estimate (fiscal years 2027, 2028, 2029, and 2030)</td><td>29</td></tr></table>\", \"description\": null, \"id\": 11, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [168, 1664, 776, 1711], \"page_id\": 90}], \"content\": \"Note\\u2014Detail may not add due to rounding. Reflects extension of authorized revenue collection and funding levels prescribed in P.L. 117-58.\", \"description\": null, \"id\": 12, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [832, 1664, 1395, 1711], \"page_id\": 90}], \"content\": \"Note\\u2014 48-month revenue estimate reflects FY 2025 Midsession Review projections.\", \"description\": null, \"id\": 13, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [1470, 97, 1503, 130], \"page_id\": 91}], \"content\": \"85\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [426, 271, 1204, 306], \"page_id\": 91}], \"content\": \"With References to Applicable Sections and Tables\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [144, 394, 801, 544], \"page_id\": 91}], \"content\": \"Amounts outstanding and in circulation (USCC)\\u2014Includes all issues by the Bureau of the Mint purposely intended as a medium of exchange. Coins sold by the Bureau of the Mint at premium prices are excluded; however, uncirculated coin sets sold at face value plus handling charge are included.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 561, 798, 681], \"page_id\": 91}], \"content\": \"Average discount rate (PDO-1, -2)\\u2014In Treasury bill auctions, purchasers tender competitive bids on a discount rate basis. The average discount rate is the weighted, or adjusted, average of all bids accepted in the auction.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 700, 805, 915], \"page_id\": 91}], \"content\": \"Budget authority (\\u201cFederal Fiscal Operations\\u201d)\\u2014Congress passes laws giving budget authority to Government entities, which gives the agencies the power to spend Federal funds. Congress can stipulate various criteria for the spending of these funds. For example, Congress can stipulate that a given agency must spend within a specific year, number of years, or any time in the future.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 931, 803, 1238], \"page_id\": 91}], \"content\": \"The basic forms of budget authority are appropriations, authority to borrow, contract authority, and authority to obligate and expend offsetting receipts and collections. The period of time during which Congress makes funds available may be specified as 1-year, multiple-year, or no-year. The available amount may be classified as either definite or indefinite; a specific amount or an unspecified amount can be made available. Authority also may be classified as current or permanent. Permanent authority requires no current action by Congress.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1252, 801, 1318], \"page_id\": 91}], \"content\": \"Budget deficit\\u2014The total, cumulative amount by which budget outlays (spending) exceed budget receipts (income).\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1329, 803, 1483], \"page_id\": 91}], \"content\": \"Cash management bills (PDO-1)\\u2014Marketable Treasury bills of irregular maturity lengths, sold periodically to fund short-term cash needs of Treasury. Their sale, having higher minimum and multiple purchase requirements than those of other issues, is generally restricted to competitive bidders.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1499, 803, 1652], \"page_id\": 91}], \"content\": \"Competitive tenders (\\\"Treasury Financing Operations\\\")\\u2014A bid to purchase a stated amount of one issue of Treasury securities at a specified yield or discount. The bid is accepted if it is within the range accepted in the auction. (See Noncompetitive tenders.)\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1664, 798, 1763], \"page_id\": 91}], \"content\": \"Currency no longer issued (USCC)\\u2014Old and new series gold and silver certificates, Federal Reserve notes, national bank notes, and 1890 Series Treasury notes.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1780, 798, 1900], \"page_id\": 91}], \"content\": \"Debt outstanding subject to limitation (FD-6)\\u2014The debt incurred by the Treasury subject to the statutory limit set by Congress. Until World War I, a specific amount of debt was authorized to each separate security issue. Beginning with the\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [736, 207, 894, 252], \"page_id\": 91}], \"content\": \"Glossary\", \"description\": null, \"id\": 11, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [641, 318, 991, 346], \"page_id\": 91}], \"content\": \"Source: Bureau of the Fiscal Service\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 391, 1488, 486], \"page_id\": 91}], \"content\": \"Second Liberty Loan Act of 1917, the nature of the limitation was modified until, in 1941, it developed into an overall limit on the outstanding Federal debt.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 502, 1490, 622], \"page_id\": 91}], \"content\": \"Pursuant to 31 U.S.C. 3101(b). By the Continuing Appropriations Act, 2018 and Bipartisan Budget Act, 2018, Public Law 115-119, the Statutory Debt Limit was suspended through March 1, 2019.\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 651, 1488, 719], \"page_id\": 91}], \"content\": \"Discount\\u2014The interest deducted in advance when purchasing notes or bonds. (See Accrued discount.)\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 731, 1488, 884], \"page_id\": 91}], \"content\": \"Discount rate (PDO-1)\\u2014The difference between par value and the actual purchase price paid, annualized over a 360-day year. Because this rate is less than the actual yield (coupon-equivalent rate), the yield should be used in any comparison with coupon issue securities.\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 900, 1488, 962], \"page_id\": 91}], \"content\": \"Dollar coins (USCC)\\u2014Include standard silver and nonsilver coins.\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 978, 1494, 1134], \"page_id\": 91}], \"content\": \"Domestic series (FD-2)\\u2014Nonmarketable, interest- and non-interest-bearing securities issued periodically by Treasury to the Resolution Funding Corporation (RFC) for investment of funds authorized under section 21B of the Federal Home Loan Bank Act (12 United States Code 1441b).\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 1148, 1488, 1268], \"page_id\": 91}], \"content\": \"Federal intrafund transactions (\\\"Federal Fiscal Operations\\\")\\u2014Intrabudgetary transactions in which payments and receipts both occur within the same Federal fund group (Federal funds or trust funds).\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 1287, 1490, 1502], \"page_id\": 91}], \"content\": \"Federal Reserve notes (USCC)\\u2014Issues by the U.S. Government to the public through the Federal Reserve banks and their member banks. They represent money owed by the Government to the public. Currently, the item \\u201cFederal Reserve notes\\u2014amounts outstanding\\u201d consists of new series issues. The Federal Reserve note is the only class of currency currently issued.\", \"description\": null, \"id\": 20, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 1518, 1490, 1763], \"page_id\": 91}], \"content\": \"Foreign-targeted issue (PDO-2)\\u2014Foreign-targeted issues were notes sold between October 1984 and February 1986 to foreign institutions, foreign branches of U.S. institutions, foreign central banks or monetary authorities, or to international organizations in which the United States held membership. Sold as companion issues, they could be converted to domestic (normal) Treasury notes with the same maturity and interest rates. Interest was paid annually.\", \"description\": null, \"id\": 21, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 1780, 1490, 1900], \"page_id\": 91}], \"content\": \"Government account series (FD-2)\\u2014Certain trust fund statutes require the Secretary of the Treasury to apply monies held by these funds toward the issuance of nonmarketable special securities. These securities are sold directly by\", \"description\": null, \"id\": 22, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1472, 101, 1499, 125], \"page_id\": 92}], \"content\": \"86\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [144, 196, 798, 438], \"page_id\": 92}], \"content\": \"Treasury to a specific Government agency, trust fund, or account. Their rate is based on an average of market yields on outstanding Treasury obligations, and they may be redeemed at the option of the holder. Roughly 80 percent of these are issued to five holders: the Federal Old-Age and Survivors Insurance Trust Fund; the civil service retirement and disability fund; the Federal Hospital Insurance Trust Fund; the military retirement fund; and the Unemployment Trust Fund.\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 457, 796, 578], \"page_id\": 92}], \"content\": \"Interfund transactions (\\\"Federal Fiscal Operations\\\")\\u2014Transactions in which payments are made from one fund group (either Federal funds or trust funds) to a receipt account in another group.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 596, 796, 745], \"page_id\": 92}], \"content\": \"International Monetary Fund transactions (\\u201cExchange Stabilization Fund\\u201d, ESF-1)\\u2014(IMF) Established by the United Nations, the IMF promotes international trade, stability of exchange, and monetary cooperation. Members are allowed to draw from the fund.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 766, 796, 915], \"page_id\": 92}], \"content\": \"Intrabudgetary transactions (\\\"Federal Fiscal Operations\\\")\\u2014These occur when payment and receipt both occur within the budget, or when payment is made from off-budget Federal entities whose budget authority and outlays are excluded from the budget totals.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 936, 796, 1056], \"page_id\": 92}], \"content\": \"Noncompetitive tenders (\\\"Treasury Financing Operations\\\")\\u2014This is a tender or bid to purchase a stated par amount of securities at the highest yield or discount rate awarded to competitive bidders for a single-price auction.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1072, 796, 1134], \"page_id\": 92}], \"content\": \"Obligations (\\\"Federal Fiscal Operations\\\")\\u2014An unpaid commitment to acquire goods or services.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1153, 798, 1332], \"page_id\": 92}], \"content\": \"Off-budget Federal entities (\\u201cFederal Fiscal Operations\\u201d)\\u2014 Federally owned and controlled entities whose transactions are excluded from the budget totals under provisions of law. Their receipts, outlays, and surplus or deficit are not included in budget receipts, outlays, or deficits. Their budget authority is not included in totals of the budget.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1353, 796, 1438], \"page_id\": 92}], \"content\": \"Outlays (\\\"Federal Fiscal Operations\\\")\\u2014Payments on obligations in the form of cash, checks, the issuance of bonds or notes, or the maturing of interest coupons.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1461, 796, 1513], \"page_id\": 92}], \"content\": \"Par value\\u2014The face value of bonds or notes, including interest.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1537, 796, 1780], \"page_id\": 92}], \"content\": \"Quarterly financing (\\\"Treasury Financing Operations\\\")\\u2014Treasury has historically offered packages of several \\\"coupon\\\" security issues on the 15th of February, May, August, and November, or on the next working day. These issues currently consist of a 3-year note, a 10-year note, and a 30-year bond. Treasury sometimes offers additional amounts of outstanding long-term notes or bonds, rather than selling new security issues. (See Reopening.)\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1798, 796, 1857], \"page_id\": 92}], \"content\": \"Fractional coins (USCC)\\u2014Coins minted in denominations of 50, 25, and 10 cents, and minor coins (5 cents and 1 cent).\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 198, 1488, 314], \"page_id\": 92}], \"content\": \"Receipts (\\\"Federal Fiscal Operations\\\")\\u2014Funds collected from selling land, capital, or services, as well as collections from the public (budget receipts), such as taxes, fines, duties, and fees.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 337, 1488, 453], \"page_id\": 92}], \"content\": \"Reopening (PDO-2)\\u2014The offer for sale of additional amounts of outstanding issues, rather than an entirely new issue. A reopened issue will always have the same maturity date, CUSIP-number, and interest rate as the original issue.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 474, 1488, 625], \"page_id\": 92}], \"content\": \"Special drawing rights (\\\"Exchange Stabilization Fund,\\\" ESF-1)\\u2014International assets created by IMF that serve to increase international liquidity and provide additional international reserves. SDRs may be purchased and sold among eligible holders through IMF. (See IMF.)\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 644, 1488, 823], \"page_id\": 92}], \"content\": \"SDR allocations are the counterpart to SDRs issued by IMF based on members' quotas in IMF. Although shown in Exchange Stabilization Fund (ESF) statements as liabilities, they must be redeemed by ESF only in the event of liquidation of, or U.S. withdrawal from, the SDR department of IMF or cancellation of SDRs.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 844, 1488, 962], \"page_id\": 92}], \"content\": \"SDR certificates are issued to the Federal Reserve System against SDRs when SDRs are legalized as money. Proceeds of monetization are deposited into an ESF account at the Federal Reserve Bank of New York.\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 983, 1488, 1040], \"page_id\": 92}], \"content\": \"Spot (\\u201cForeign Currency Positions\\u201d)\\u2014Due for receipt or delivery within 2 workdays.\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 1061, 1488, 1362], \"page_id\": 92}], \"content\": \"State and local government series (SLGS) (FD-2)\\u2014Special nonmarketable certificates, notes, and bonds offered to State and local governments as a means to invest proceeds from their own tax-exempt financing. Interest rates and maturities comply with IRS arbitrage provisions. SLGS are offered in both time deposit and demand deposit forms. Time deposit certificates have maturities of up to 1 year. Notes mature in 1 to 10 years and bonds mature in more than 10 years. Demand deposit securities are 1-day certificates rolled over with a rate adjustment daily.\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 1384, 1488, 1591], \"page_id\": 92}], \"content\": \"Statutory debt limit (FD-6)\\u2014By Act of Congress there is a limit, either temporary or permanent, on the amount of public debt that may be outstanding. When this limit is reached, Treasury may not sell new debt issues until Congress increases or extends the limit. For a detailed listing of changes in the limit since 1941, see the Budget of the United States Government. (See debt outstanding subject to limitation.)\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 1612, 1488, 1822], \"page_id\": 92}], \"content\": \"STRIPS (PDO-2)\\u2014Separate Trading of Registered Interest and Principal Securities. Long-term notes and bonds may be divided into principal and interest-paying components, which may be transferred and sold in amounts as small as $1,000. STRIPS are sold at auction at a minimum par amount, varying for each issue. The amount is an arithmetic function of the issue\\u2019s interest rate.\", \"description\": null, \"id\": 20, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1470, 99, 1501, 123], \"page_id\": 93}], \"content\": \"87\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [138, 191, 796, 283], \"page_id\": 93}], \"content\": \"Treasury bills\\u2014The shortest term Federal security (maturity dates normally varying from 3 to 12 months), are sold at a discount.\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 304, 796, 394], \"page_id\": 93}], \"content\": \"Trust fund transaction (\\\"Federal Fiscal Operations\\\")\\u2014An intrabudgetary transaction in which both payments and receipts occur within the same trust fund group.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 191, 1494, 316], \"page_id\": 93}], \"content\": \"United States\\u2014Includes the 50 States, District of Columbia, Commonwealth of Puerto Rico, American Samoa, Midway Island, Virgin Islands, Wake Island, and all other territories and possessions.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 337, 1494, 422], \"page_id\": 93}], \"content\": \"U.S. notes (USCC)\\u2014Legal tender notes of five different issues: 1862 ($5-$1,000 notes); 1862 ($1-$2 notes); 1863 ($5-$1,000 notes); 1863 ($1-$10,000 notes); and 1901 ($10 notes).\", \"description\": null, \"id\": 4, \"type\": \"text\"}], \"pages\": [{\"id\": 1, \"image_uri\": null}, {\"id\": 2, \"image_uri\": null}, {\"id\": 3, \"image_uri\": null}, {\"id\": 4, \"image_uri\": null}, {\"id\": 5, \"image_uri\": null}, {\"id\": 6, \"image_uri\": null}, {\"id\": 7, \"image_uri\": null}, {\"id\": 8, \"image_uri\": null}, {\"id\": 9, \"image_uri\": null}, {\"id\": 10, \"image_uri\": null}, {\"id\": 11, \"image_uri\": null}, {\"id\": 12, \"image_uri\": null}, {\"id\": 13, \"image_uri\": null}, {\"id\": 14, \"image_uri\": null}, {\"id\": 15, \"image_uri\": null}, {\"id\": 16, \"image_uri\": null}, {\"id\": 17, \"image_uri\": null}, {\"id\": 18, \"image_uri\": null}, {\"id\": 19, \"image_uri\": null}, {\"id\": 20, \"image_uri\": null}, {\"id\": 21, \"image_uri\": null}, {\"id\": 22, \"image_uri\": null}, {\"id\": 23, \"image_uri\": null}, {\"id\": 24, \"image_uri\": null}, {\"id\": 25, \"image_uri\": null}, {\"id\": 26, \"image_uri\": null}, {\"id\": 27, \"image_ur